public class Main {
    static void print(Object obj) {
        if (!(obj instanceof String s)) {
            System.out.println("N");
            return;
        }
        if (s.length() < 3) {
            System.out.println("S");
            return;
        }
        System.out.println(s.toUpperCase());
    }
    public static void main(String[] args) {
        Object value = "java";
        print(value);
    }
}

public class Main {
    public static void main(String[] args) {
        int n = 0;
        var result = switch (n) {
            case 0 -> "Z";
            case 1, 2 -> "L";
            case 3 -> {
                int x = n + 7;
                yield "Y" + x;
            }
            default -> "D";
        };
        System.out.println(result);
    }
}

