        }
    }
}

public class Main {
    static int calc(int x) {
        try {
            if (x < 0) {
                throw new IllegalArgumentException();
            }
            return x + 1;
        } catch (IllegalArgumentException e) {
            return 10;
        } finally {
            if (x == 0) {
                return 20;
            }
            System.out.print("F");
        }
    }
    public static void main(String[] args) {
        System.out.println(calc(-1));
    }
}

